messages.body_plain:
Hello,

one issue connected with 0 size (switched off) parameters is that setting init values is problematic, because:

1) if I define an init value for standard (size > 0) parameter I must define an init value for 0 size parameters as well

AND

2) there is not (apparently) an object in R that satisfies the stan condition "dims declared=(0)"

SO

I get this error

SAMPLING FOR MODEL 'BayesSort' NOW (CHAIN 2).
[1] "Error : Initialization from source failed."
[2] "mismatch in number dimensions declared and found in context; processing stage=initialization; variable name=sigma; dims declared=(0); dims found=()"

A question is: can I specify the init value for one parameter only?

I attach part of my model and the command I am using to run it

data {

  int<lower=0, upper=1> is_disease;
 int<lower=0, upper=1> is_hidden;
 int<lower=0, upper=1> is_bias;

  //-------------------------------//
 //   Dirichlet variables         //
 //-------------------------------//

  int<lower=2> K;                       // num topics
 int<lower=2> W;                       // num words
 int<lower=1> M;                       // num docs

  vector<lower=0>[K] alpha;             // hyperparameter of theta
 vector<lower=0>[W] counts[M];         //gene counts
 vector<lower=0>[W] phi_given[K];      //word in topic probability is normal log shaped

  //-------------------------------//
 //   linear regression           //
 //-------------------------------//

  int<lower=0> maxPoly;                 //max order polynomia I can have
 vector[W] c[K];                       //parameter of linear functions
 vector[W] a[maxPoly, K];              //parameter of linear functions

  //-------------------------------//
 //   unknown population          //
 //-------------------------------//

  vector[W] lg_mu;
 cov_matrix[W] lg_sigma;

  //-------------------------------//
 //   cell isolation bias         //
 //-------------------------------//

  int<lower=1> batches[K];
 int<lower=1> num_batches;

  //-------------------------------//

}

transformed data{

  vector[W] counts_10[M];
 vector[2] k_n_hyper;
 int M_phi;                            //This is for avoiding to loop in documents when is_disease is FALSE
 int M_to_M_phi[M];                    //This is for avoiding to loop in documents when is_disease is FALSE

  //-------------------------------//
 //- Numerical log stability      //
 //-------------------------------//
  for(m in 1:M) counts_10[m] <- exp(log(counts[m]) + 10);

  //-------------------------------//
 //   unknown population          //
 //-------------------------------//

  for(u in 1:2) k_n_hyper[u] <- 1;

  //-------------------------------//
 //   linear regression           //
 //-------------------------------//

  if(is_disease) {
   M_phi <- M;
   for(m in 1:M) M_to_M_phi[m] <- m;
 }
 else {
   M_phi <- 1;
   for(m in 1:M) M_to_M_phi[m] <- 1;
 }
  //-------------------------------//

}

parameters {

  //-------------------------------//
 //   topic probability           //
 //-------------------------------//

  simplex[K] theta[M];   // topic distribution for doc m

  //-------------------------------//
 //   linear regression           //
 //-------------------------------//

  vector<lower=1-0.1, upper=maxPoly+1+0.1>[M * is_disease] sigma; //activation/disease state
 vector<lower=0>[W * is_disease] err[K * is_disease]; //standard deviation of the linear equations

  //-------------------------------//
 //   unknown population          //
 //-------------------------------//

  vector[W * is_hidden] gamma;
 simplex[2 * is_hidden] known_unknown[M * is_hidden];

  //-------------------------------//
 //   cell isolation bias         //
 //-------------------------------//

  #vector<lower=1, upper=100> [num_batches * is_bias]  bias_magnitude;
 #real<lower=1, upper=100> bias_magnitude;
 vector<lower=0> [W * is_bias] perturbation[num_batches * is_bias];

 //-------------------------------//
}

inits_list <- list(
      theta = do.call("rbind", rep(data.frame(rep(1/K, my.in$K)), my.in$M)),
     sigma = c(0),
     err = c(0),
     gamma = c(0),
     known_unknown = c(0),
     perturbation = c(0)
   );

    if(is_disease) {
     inits_list$sigma <- rep(1, my.in$M)
     inits_list$err <- do.call("rbind", rep(data.frame(rep(0, my.in$W)), my.in$K))
   }
   if(is_hidden) {
     inits_list$gamma <- rep(mean(as.vector(phi_given)), my.in$W)
     inits_list$known_unknown <- c(0.5, 0.5)
   }
   if(is_bias) inits_list$perturbation = rep(1, my.in$W)

    inits <- function() { inits_list }

    fit <-
     stan(
       file = algorithm_file,
       data = my.in,
       iter = 500,
       init = inits
     )

The error is easily reproducible on a dummy model.

when there are 0 size parameters initial values cannot be set for any other parameter. At list this is what I came across.

I hope a solution is possible, because I am close to publish my model.

Thanks a lot.
Stefano

